class Solution {
    public boolean isValid(String s) {
        StringBuilder sb = new StringBuilder(s);
        int idx;
        while (sb.length() > 0) {
            String cur = sb.toString();
            idx = cur.indexOf("abc");
            if (idx == -1) return false;
            sb.delete(idx, idx + 3);
        }
        return true;
    }
}

