class Solution {
    public boolean isValid(String s) {
        StringBuilder st = new StringBuilder();
        for (char ch : s.toCharArray()) {
            st.append(ch);
            int n = st.length();
            if (n >= 3 && st.charAt(n-3) == 'a' && st.charAt(n-2) == 'b' && st.charAt(n-1) == 'c')
                st.setLength(n - 3);
        }
        return st.length() == 0;
    }
}

